CREATE OR REPLACE FUNCTION public.audience_access(p_workspace uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text;
begin
 perform zoi.assert_ws(p_workspace);
 v_role:=zoi.audience_asset_role(p_workspace,false);
 return jsonb_build_object('ok',true,'workspace_id',p_workspace,'role',v_role,'can_write',v_role in ('owner','admin','editor'),'can_record_consent',coalesce(zoi.ops_role(p_workspace) in ('owner','admin','editor'),false));
end; $function$

CREATE OR REPLACE FUNCTION public.email_consent_record(p_workspace uuid, p_email text, p_name text, p_tags text[], p_source text, p_consented_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT COALESCE(zoi.is_ws_member(p_workspace),false) THEN RAISE EXCEPTION 'not_authorized'; END IF;
 IF NOT EXISTS (SELECT 1 FROM zoi.workspace_members m JOIN zoi.user_profiles p ON p.id=m.profile_id WHERE m.workspace_id=p_workspace AND p.auth_user_id=auth.uid() AND m.role IN ('owner','admin','editor')) THEN RAISE EXCEPTION 'insufficient_permission'; END IF;
 IF length(COALESCE(p_email,''))>254 OR length(COALESCE(p_name,''))>200 OR length(COALESCE(p_source,''))>2000 OR cardinality(COALESCE(p_tags,'{}'))>50 OR EXISTS(SELECT 1 FROM unnest(p_tags) tag WHERE length(tag)>100) THEN RAISE EXCEPTION 'consent_field_too_large'; END IF;
 IF length(btrim(COALESCE(p_source,''))) < 8 OR p_consented_at IS NULL OR p_consented_at > now() THEN RAISE EXCEPTION 'consent_evidence_required'; END IF;
 INSERT INTO zoi.email_subscriptions(workspace_id,email,name,tags,status,consent_source,consented_at,recorded_by)
 VALUES(p_workspace,lower(btrim(p_email)),COALESCE(p_name,''),COALESCE(p_tags,'{}'),'subscribed',btrim(p_source),p_consented_at,auth.uid())
 ON CONFLICT(workspace_id,email) DO UPDATE SET name=EXCLUDED.name,tags=EXCLUDED.tags,
   consent_source=EXCLUDED.consent_source,consented_at=EXCLUDED.consented_at,recorded_by=EXCLUDED.recorded_by,updated_at=now()
 WHERE zoi.email_subscriptions.status='subscribed';
 IF NOT FOUND THEN RAISE EXCEPTION 'suppressed_address_cannot_be_resubscribed_by_import'; END IF;
 RETURN jsonb_build_object('ok',true);
END; $function$

CREATE OR REPLACE FUNCTION public.email_campaign_save(p_workspace uuid, p_subject text, p_body text, p_preheader text DEFAULT NULL::text, p_from_name text DEFAULT NULL::text, p_audience_tag text DEFAULT NULL::text, p_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'zoi', 'public'
AS $function$
DECLARE v uuid;
BEGIN
  PERFORM zoi.assert_workspace_write(p_workspace);
  IF p_id IS NOT NULL THEN
    UPDATE zoi.email_campaigns SET subject=COALESCE(p_subject,''), body=COALESCE(p_body,''), preheader=p_preheader,
      from_name=p_from_name, audience_tag=NULLIF(trim(p_audience_tag),''), updated_at=now()
    WHERE id=p_id AND workspace_id=p_workspace AND status='draft' RETURNING id INTO v;
    IF v IS NULL THEN RAISE EXCEPTION 'not_editable'; END IF;
  ELSE
    INSERT INTO zoi.email_campaigns(workspace_id,subject,body,preheader,from_name,audience_tag)
    VALUES(p_workspace,COALESCE(p_subject,''),COALESCE(p_body,''),p_preheader,p_from_name,NULLIF(trim(p_audience_tag),''))
    RETURNING id INTO v;
  END IF;
  RETURN v;
END;$function$

CREATE OR REPLACE FUNCTION zoi.assert_workspace_write(p_workspace uuid, p_roles text[] DEFAULT ARRAY['owner'::text, 'admin'::text, 'editor'::text])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text;
begin r:=zoi.workspace_locked_role(p_workspace);
 if not coalesce(r=any(p_roles),false) then raise exception 'insufficient_permission' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION zoi.workspace_locked_role(p_workspace uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p uuid; o uuid; r text;
begin
 if auth.uid() is null then raise exception 'not_signed_in' using errcode='42501';end if;
 select id into p from zoi.user_profiles where auth_user_id=auth.uid();
 -- Match team writers: workspace first also serializes absent-member inserts.
 select owner_profile_id into o from zoi.workspaces where id=p_workspace for update;
 if not found or p is null then raise exception 'no_access_to_workspace' using errcode='42501';end if;
 select role into r from zoi.workspace_members where workspace_id=p_workspace and profile_id=p for share;
 if not found and o=p then r:='owner';end if;
 if r='owner' and o is distinct from p then r:='viewer';end if;
 if coalesce(r,'') not in('owner','admin','editor','viewer') then raise exception 'no_access_to_workspace' using errcode='42501';end if;
 perform zoi.suite_lock_session();
 return r;
end $function$

CREATE OR REPLACE FUNCTION zoi.suite_current_session()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid text:=auth.jwt()->>'session_id';
begin
 if auth.uid() is null or coalesce(sid,'') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.users where id=auth.uid() and deleted_at is null and coalesce(is_anonymous,false)=false and (banned_until is null or banned_until<=clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.sessions where id=sid::uuid and user_id=auth.uid() and (not_after is null or not_after>clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION zoi.suite_lock_session()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid text:=auth.jwt()->>'session_id';
begin
 if auth.uid() is null or coalesce(sid,'') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.users where id=auth.uid() and deleted_at is null and coalesce(is_anonymous,false)=false and (banned_until is null or banned_until<=clock_timestamp()) for share;
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.sessions where id=sid::uuid and user_id=auth.uid() and (not_after is null or not_after>clock_timestamp()) for share;
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION zoi.workspace_current_role(p_workspace uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p uuid; o uuid; r text;
begin
 if auth.uid() is null then raise exception 'not_signed_in' using errcode='42501';end if;
 select id into p from zoi.user_profiles where auth_user_id=auth.uid();
 select owner_profile_id into o from zoi.workspaces where id=p_workspace;
 if not found or p is null then raise exception 'no_access_to_workspace' using errcode='42501';end if;
 select role into r from zoi.workspace_members where workspace_id=p_workspace and profile_id=p;
 if not found and o=p then r:='owner';end if;
 if r='owner' and o is distinct from p then r:='viewer';end if;
 if coalesce(r,'') not in('owner','admin','editor','viewer') then raise exception 'no_access_to_workspace' using errcode='42501';end if;
 perform zoi.suite_current_session();
 return r;
end $function$
